<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeAsset\Application\Usecase\Create;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Document\ThemeAsset\Application\Service\Visibility\ThemeAssetVisibilityService;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ThemeAsset;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway\ThemeAssetWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ThemeAssetCreateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ThemeAssetVisibilityService $visibility,
        private readonly ThemeAssetWriteGateway $writer,
    ) {
    }

    public function allowCreate(): Allow
    {
        $this->logDebug("Check allow of create usecase for Theme asset");
        $span = $this->startSpan("Check allow of create usecase for Theme asset");
        try {
            $result = $this->dispatcher->dispatch(new ThemeAssetCreateAllowDecision(Allow::allowed('create', 'Allowed to create by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function create(ThemeAssetCreateParams $params): ThemeAssetCreateResult
    {
        $this->logDebug("Run create usecase for Theme asset");
        $span = $this->startSpan("Run create usecase for Theme asset");
        try {
            $allow = $this->allowCreate();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to create Theme asset');
            }
            $this->dispatcher->dispatch(new ThemeAssetCreateCheck($params));
            $enriched = $this->dispatcher->dispatch(new ThemeAssetCreateEnrich($params, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $entity = ThemeAsset::create($input);
            $result = $this->writer->create(
                $entity,
                fn (ThemeAsset $created) =>
                            $this->visibility->checkVisibility($created)
            );
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new ThemeAssetCreateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
